//! Tests for type checker (eta).
//
// Generated by splitting tc/tests.rs into submodules for maintainability.

use super::*;

#[test]
fn test_eta_expansion_basic() {
    // (λ x. f x) should be definitionally equal to f
    // when f : A → B
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Define f : Prop → Prop
    let f_type = Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop());
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: f_type,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let f = Expr::const_(Name::from_string("f"), vec![]);

    // λ x : Prop. f x
    // Note: inside the lambda, f needs to stay the same (it's a constant, not a bvar)
    // so the body is: App(f, BVar(0))
    let eta_expanded = Expr::lam(
        BinderInfo::Default,
        Expr::prop(),
        Expr::app(f.clone(), Expr::bvar(0)),
    );

    // f and (λ x. f x) should be definitionally equal by eta
    assert!(
        tc.is_def_eq(&f, &eta_expanded),
        "Eta expansion: f should equal (λ x. f x)"
    );
    assert!(
        tc.is_def_eq(&eta_expanded, &f),
        "Eta expansion: (λ x. f x) should equal f"
    );
}

#[test]
fn test_eta_expansion_nested() {
    // (λ x y. f x y) should be definitionally equal to f
    // when f : A → B → C
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Define f : Prop → Prop → Prop
    let f_type = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),
        Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop()),
    );
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: f_type,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let f = Expr::const_(Name::from_string("f"), vec![]);

    // λ x : Prop. λ y : Prop. f x y
    // Inner body: App(App(f, BVar(1)), BVar(0))
    // Outer body: Lam(Prop, App(App(f, BVar(1)), BVar(0)))
    let inner_body = Expr::app(Expr::app(f.clone(), Expr::bvar(1)), Expr::bvar(0));
    let inner_lam = Expr::lam(BinderInfo::Default, Expr::prop(), inner_body);
    let eta_expanded = Expr::lam(BinderInfo::Default, Expr::prop(), inner_lam);

    // f and (λ x y. f x y) should be definitionally equal by eta
    assert!(
        tc.is_def_eq(&f, &eta_expanded),
        "Nested eta expansion: f should equal (λ x y. f x y)"
    );
}

#[test]
fn test_eta_no_expansion_different_body() {
    // (λ x. g) should NOT equal f unless g = f x
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Define f : Prop → Prop
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop()),
    })
    .unwrap();

    // Define g : Prop
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("g"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    // λ x : Prop. g (constant function, ignores x)
    let const_lambda = Expr::lam(BinderInfo::Default, Expr::prop(), g);

    // f and (λ x. g) should NOT be equal
    assert!(
        !tc.is_def_eq(&f, &const_lambda),
        "Non-eta lambda should not equal f"
    );
}

#[test]
fn test_eta_with_type_mismatch() {
    // (λ x : A. f x) should NOT equal g : B → C when A ≠ B
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Define f : Prop → Prop
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop()),
    })
    .unwrap();

    // Define g : Type → Type
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("g"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::type_(), Expr::type_()),
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    // λ x : Prop. f x
    let lam_f = Expr::lam(
        BinderInfo::Default,
        Expr::prop(),
        Expr::app(f, Expr::bvar(0)),
    );

    // lam_f : Prop → Prop
    // g : Type → Type
    // These should NOT be equal even with eta expansion
    assert!(
        !tc.is_def_eq(&lam_f, &g),
        "Lambda with different domain type should not equal via eta"
    );
}

// =========================================================================
// Eta expansion with incomplete type inference (Risk R5)
// =========================================================================

/// Test that eta expansion works when the non-lambda side is a Let-bound
/// function.
///
/// try_eta_expansion_impl calls try_infer_type_quick(other) which returns
/// None for Let expressions in `tc/def_eq/mod.rs`. This means eta expansion
/// between (λ x. f x) and (let y := ... in f) will fail even when
/// semantically equivalent.
///
/// This test documents the current behavior (failure = false negative).
/// If try_infer_type_quick is later extended to handle Let, this test
/// should be updated to expect success.
///
/// Risk R5: eta expansion incomplete inference for Pi/Let-typed expressions.
#[test]
fn test_eta_expansion_let_bound_function_known_limitation() {
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Define f : Prop → Prop
    let f_type = Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop());
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: f_type,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let f = Expr::const_(Name::from_string("f"), vec![]);

    // λ x : Prop. f x
    let eta_expanded = Expr::lam(
        BinderInfo::Default,
        Expr::prop(),
        Expr::app(f.clone(), Expr::bvar(0)),
    );

    // let y : (Prop → Prop) := f in y
    // This is semantically f, but wrapped in a Let expression.
    let let_f = Expr::let_named(
        Name::anon(),
        Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop()),
        f.clone(),
        Expr::bvar(0), // body refers to the let-bound variable
        false,
    );

    // Lean 4 can prove these equal (full type inference handles Let).
    // clean currently fails because try_infer_type_quick returns None for Let.
    //
    // Note: is_def_eq may still succeed through OTHER paths (e.g., whnf reducing
    // the Let to f first). We test specifically whether the result is correct,
    // not the mechanism.
    let result = tc.is_def_eq(&eta_expanded, &let_f);

    // The Let should be reduced by whnf before eta is attempted, so is_def_eq
    // should actually succeed here (whnf of `let y := f in y` is just `f`).
    // This test verifies the whnf-before-eta path compensates for the quick
    // inference limitation.
    assert!(
        result,
        "Eta: (λ x. f x) should equal (let y := f in y) after whnf reduces the Let"
    );
}

/// Test eta expansion where the non-lambda side's type requires full inference.
///
/// This exercises the specific gap: when `other` is an FVar whose type is a
/// Pi type, try_infer_type_quick succeeds (FVar types are in the local context).
/// But when `other` is a complex expression like a projection whose result type
/// is a Pi, try_infer_type_quick may fail.
///
/// We test with a simple FVar case first to establish the baseline, then show
/// the gap exists for expressions that need deeper inference.
#[test]
fn test_eta_expansion_fvar_with_pi_type_succeeds() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // We need the FVar's type to be a Pi type (Prop → Prop)
    let pi_type = Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop());

    // Create a fresh FVar with type (Prop → Prop) in the local context
    let fvar_id =
        tc.ctx
            .borrow_mut()
            .push(Name::from_string("h"), pi_type.clone(), BinderInfo::Default);

    let fvar = Expr::fvar(fvar_id);

    // λ x : Prop. fvar x
    let eta_expanded = Expr::lam(
        BinderInfo::Default,
        Expr::prop(),
        Expr::app(
            Expr::fvar(fvar_id), // Inside lambda, fvar is still the same (not a bvar)
            Expr::bvar(0),
        ),
    );

    // try_infer_type_quick(fvar) should succeed because FVar types are in
    // the local context. So eta expansion should work.
    assert!(
        tc.is_def_eq(&eta_expanded, &fvar),
        "Eta: (λ x. fvar x) should equal fvar when fvar : Prop → Prop"
    );
    assert!(
        tc.is_def_eq(&fvar, &eta_expanded),
        "Eta: fvar should equal (λ x. fvar x) when fvar : Prop → Prop (symmetric)"
    );
}

