// Structure eta expansion tests (#1516)
// =========================================================================

/// Regression test for #1516: infer_proj_type_from O(n^2) WHNF calls.
///
/// Creates an 8-field structure and verifies that struct eta expansion
/// works correctly through `is_def_eq`. Before the fix, each projection
/// field type inference walked 0..idx Pi types (O(n^2) total). After the
/// fix, the batch projection cache populates all field types in one pass
/// on both the strict and quick paths.
#[test]
fn test_struct_eta_8_field_exercises_batch_cache() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_nat().expect("init_nat");

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);
    let s8_name = Name::from_string("S8");
    let s8_ref = Expr::const_(s8_name.clone(), vec![]);

    // S8.mk : Nat → Nat → Nat → Nat → Nat → Nat → Nat → Nat → S8
    let mut ctor_type = s8_ref.clone();
    for _ in 0..8 {
        ctor_type = Expr::pi(BinderInfo::Default, nat.clone(), ctor_type);
    }

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: s8_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: Name::from_string("S8.mk"),
                type_: ctor_type,
            }],
        }],
    })
    .expect("add S8");

    let tc = TypeChecker::new(&env);

    // Create FVar x : S8
    let x_id =
        tc.ctx
            .borrow_mut()
            .push(Name::from_string("x"), s8_ref.clone(), BinderInfo::Default);
    let x = Expr::fvar(x_id);

    // Build S8.mk (proj 0 x) (proj 1 x) ... (proj 7 x)
    let mut expanded = Expr::const_(Name::from_string("S8.mk"), vec![]);
    for field_idx in 0..8u32 {
        let proj = Expr::proj(s8_name.clone(), field_idx, x.clone());
        expanded = Expr::app(expanded, proj);
    }

    // x and S8.mk (proj 0 x) ... (proj 7 x) should be def-eq via struct eta.
    // This exercises the quick projection type inference path through
    // is_def_eq_structural → try_eta_struct → expand_eta_struct, which now
    // benefits from the batch projection cache (#1516).
    assert!(
        tc.is_def_eq(&x, &expanded),
        "x : S8 should equal S8.mk (proj 0 x) ... (proj 7 x) via struct eta"
    );
    assert!(
        tc.is_def_eq(&expanded, &x),
        "S8.mk (proj 0 x) ... (proj 7 x) should equal x : S8 (symmetric)"
    );
}

/// Test struct eta with dependent field types (field types reference earlier fields).
///
/// Sigma-like structure: Sig.mk : (a : Nat) → (b : Nat) → Sig
/// where field b's type could depend on field a (though here both are Nat).
/// Verifies the batch cache correctly handles the instantiation for dependent
/// telescope walks.
#[test]
fn test_struct_eta_dependent_fields_batch_cache() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_nat().expect("init_nat");

    let nat = Expr::const_(Name::from_string("Nat"), vec![]);

    // Create a structure with 4 fields, all Nat (non-dependent for simplicity).
    let s4_name = Name::from_string("S4");
    let s4_ref = Expr::const_(s4_name.clone(), vec![]);
    let mut ctor_type = s4_ref.clone();
    for _ in 0..4 {
        ctor_type = Expr::pi(BinderInfo::Default, nat.clone(), ctor_type);
    }

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: s4_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: Name::from_string("S4.mk"),
                type_: ctor_type,
            }],
        }],
    })
    .expect("add S4");

    let tc = TypeChecker::new(&env);

    // Create two FVars of type S4
    let a_id =
        tc.ctx
            .borrow_mut()
            .push(Name::from_string("a"), s4_ref.clone(), BinderInfo::Default);
    let b_id =
        tc.ctx
            .borrow_mut()
            .push(Name::from_string("b"), s4_ref.clone(), BinderInfo::Default);
    let a = Expr::fvar(a_id);
    let b = Expr::fvar(b_id);

    // Build S4.mk (proj 0 a) (proj 1 a) (proj 2 a) (proj 3 a)
    let mut a_expanded = Expr::const_(Name::from_string("S4.mk"), vec![]);
    for i in 0..4u32 {
        a_expanded = Expr::app(a_expanded, Expr::proj(s4_name.clone(), i, a.clone()));
    }

    // a and its eta-expansion should be def-eq
    assert!(
        tc.is_def_eq(&a, &a_expanded),
        "a : S4 should equal its eta expansion"
    );

    // Two different FVars should NOT be def-eq even after eta expansion
    assert!(
        !tc.is_def_eq(&a, &b),
        "distinct FVars of same struct type should not be def-eq"
    );

    // But each FVar should equal its own eta expansion
    let mut b_expanded = Expr::const_(Name::from_string("S4.mk"), vec![]);
    for i in 0..4u32 {
        b_expanded = Expr::app(b_expanded, Expr::proj(s4_name.clone(), i, b.clone()));
    }
    assert!(
        tc.is_def_eq(&b, &b_expanded),
        "b : S4 should equal its eta expansion"
    );
}

